from __future__ import annotations

from typing import Any, Callable


class DataFilter:
    def __init__(self, predicate: Callable[[Any], bool]) -> None:
        self.predicate = predicate

    def apply(self, data: list[Any]) -> list[Any]:
        return [item for item in data if self.predicate(item)]


class DataTransformer:
    _MISSING = object()

    def __init__(self, transform_fn: Callable[[Any], Any]) -> None:
        self.transform_fn = transform_fn
        self._cache: dict[Any, Any] = {}

    def apply(self, data: list[Any]) -> list[Any]:
        return [self._cached_transform(item) for item in data]

    def _cached_transform(self, item: Any) -> Any:
        try:
            cached = self._cache.get(item, self._MISSING)
            if cached is not self._MISSING:
                return cached
            result = self.transform_fn(item)
            self._cache[item] = result
            return result
        except TypeError:
            return self.transform_fn(item)

    def clear_cache(self) -> None:
        self._cache.clear()


class DataPipeline:
    def __init__(self, data_filter: DataFilter | None, transformer: DataTransformer | None) -> None:
        self.data_filter = data_filter
        self.transformer = transformer

    def execute(self, data: list[Any]) -> list[Any]:
        result = data
        if self.data_filter:
            result = self.data_filter.apply(result)
        if self.transformer:
            result = self.transformer.apply(result)
        return result


class DataProcessor:
    """Facade that hides filter/transform/cache subsystems behind a simple process() call."""

    def __init__(self, config: dict[str, Any]) -> None:
        self._data_filter = DataFilter(config["filter"]) if config.get("filter") else None
        self._transformer = DataTransformer(config["transform"]) if config.get("transform") else None
        self._pipeline = DataPipeline(self._data_filter, self._transformer)

    def __enter__(self) -> DataProcessor:
        return self

    def __exit__(self, exc_type: type | None, exc_val: BaseException | None, exc_tb: Any) -> bool:
        if self._transformer:
            self._transformer.clear_cache()
        return False

    def process(self, data: list[Any]) -> list[Any]:
        return self._pipeline.execute(data)

